SELECT pg_temp.denied($q$UPDATE produtos SET company_id='b6000000-0000-4000-8000-000000000002' WHERE id='c6000000-0000-4000-8000-000000000001'$q$,'tenant immutable','42501');
SELECT pg_temp.denied($q$INSERT INTO produtos(id,company_id,nome_produto,sku,categoria,unidade_medida) VALUES('c6000000-0000-4000-8000-000000000003','b6000000-0000-4000-8000-000000000001','Produto 3','SAME-SKU','Outros','UN')$q$,'duplicate SKU same tenant','23505');
SELECT pg_temp.denied($q$SELECT deactivate_produto('c6000000-0000-4000-8000-000000000002')$q$,'B resource refused in A','42501');
WITH changed AS (UPDATE produtos SET nome_produto='Intruder' WHERE id='c6000000-0000-4000-8000-000000000002' RETURNING id) SELECT pg_temp.ok(count(*)=0,'A update B changes no rows') FROM changed;
SELECT pg_temp.denied($q$UPDATE produtos SET ativo=false WHERE id='c6000000-0000-4000-8000-000000000001'$q$,'even editor uses dedicated deactivate','42501');
SELECT pg_temp.context(4,1);
SELECT pg_temp.ok((SELECT count(*)=1 AND bool_and(company_id='b6000000-0000-4000-8000-000000000001') FROM produtos),'multi or super selected scope 4-1');
