SELECT pg_temp.ok((SELECT nome_produto='Edit only' FROM produtos WHERE id='c6000000-0000-4000-8000-000000000007'),'edit-only writes');
SELECT pg_temp.denied($q$INSERT INTO produtos(id,company_id,nome_produto,sku,categoria,unidade_medida) VALUES('c6000000-0000-4000-8000-000000000008','b6000000-0000-4000-8000-000000000001','Produto 8','SAME-SKU','Outros','UN')$q$,'edit-only no create','42501');
SELECT pg_temp.denied($q$SELECT generate_next_sku()$q$,'edit-only no allocate SKU','42501');
SELECT pg_temp.denied($q$SELECT deactivate_produto('c6000000-0000-4000-8000-000000000007')$q$,'edit-only no deactivate','42501');
