WITH changed AS (DELETE FROM produtos RETURNING id) SELECT pg_temp.ok(count(*)=0,'catalog delete-only no physical DELETE') FROM changed;
SELECT pg_temp.denied($q$SELECT generate_next_sku()$q$,'delete-only no SKU','42501');
SELECT pg_temp.denied($q$SELECT deactivate_produto(NULL)$q$,'null ID denied','42501');
