CREATE FUNCTION pg_temp.fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'INJECTED_FAILURE'; END$$;
CREATE TRIGGER phase6_test_fail BEFORE INSERT ON audit_logs FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_audit();
SET LOCAL ROLE authenticated;
SELECT pg_temp.context(9);
SELECT pg_temp.denied($q$SELECT deactivate_produto('c6000000-0000-4000-8000-000000000007')$q$,'late audit failure rolls back','P0001');
RESET ROLE;
DROP TRIGGER phase6_test_fail ON audit_logs;
SELECT pg_temp.ok(pg_temp.digest()=(SELECT value FROM resources WHERE name='after-soft'),'late failure preserves digest including logs');
SELECT pg_temp.ok((SELECT bool_and(ativo) FROM produtos WHERE company_id='b6000000-0000-4000-8000-000000000002'),'B unaffected by all A operations');
-- Catálogo -> consumer real: mesmo produto recém-criado, preço e movimento atômico.
UPDATE user_permissions SET effect='ALLOW' WHERE user_id='a6000000-0000-4000-8000-000000000001' AND permission_key IN ('compras:fornecedores:edit','estoque:movimentacoes:create');
SET LOCAL ROLE authenticated;
