SELECT pg_temp.ok((SELECT count(*)=1 FROM supplier_item_prices WHERE stock_item_id='c6000000-0000-4000-8000-000000000007'),'deactivate preserves supplier link');
SAVEPOINT service_check;
SET LOCAL ROLE service_role;
UPDATE produtos SET observacoes='Service fixture' WHERE id='c6000000-0000-4000-8000-000000000007';
SELECT pg_temp.ok((SELECT observacoes='Service fixture' FROM produtos WHERE id='c6000000-0000-4000-8000-000000000007'),'real service legitimate update');
SELECT pg_temp.denied($q$UPDATE produtos SET company_id='b6000000-0000-4000-8000-000000000002' WHERE id='c6000000-0000-4000-8000-000000000007'$q$,'real service cannot retarget product tenant');
RESET ROLE;
-- Manter os resultados; a transação inteira abaixo reverte os dados sintéticos.
SELECT count(*) AS assertions FROM results;
ROLLBACK;
